"""Tiny wc. Usage: python wc.py [--lines] [--words] [--chars] [--top N] FILE"""
import argparse
import sys


def count(text):
    return {"lines": len(text.splitlines()), "words": len(text.split())}


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("file")
    ap.add_argument("--lines", action="store_true")
    ap.add_argument("--words", action="store_true")
    ap.add_argument("--chars", action="store_true")
    ap.add_argument("--top", type=int)
    a = ap.parse_args(argv)
    with open(a.file) as f:
        text = f.read()
    c = count(text)
    selected = [k for k in ("lines", "words", "chars") if getattr(a, k)] or ["lines", "words"]
    for k in selected:
        print(f"{k} {c[k]}")
    if a.top is not None:
        counts = {}
        for word in text.split():
            counts[word] = counts.get(word, 0) + 1
        for word, n in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0])[:a.top]):
            print(f"{word} {n}")
    return 0


if __name__ == "__main__":
    sys.exit(main())


